actions.script:
const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const CODES = {CrtDirect: 'direct', CrtPrivate: 'private', CrtPublic: 'public', CrtRecord: 'record'}
const DEFAULT_VISIBILITY = {CrtDirect: 'CrvMembers', CrtPrivate: 'CrvMembers', CrtPublic: 'CrvUsers', CrtRecord: 'CrvRecord'}
const ROLE_LEVEL = {CmrOwner: 4, CmrModerator: 3, CmrMember: 2, CmrAgent: 2}
level = 0; room = null; member = null
isMember = false; canRead = false; canJoin = false; canPost = false; canModerate = false; isOwner = false; isArchived = false
const currentUserId = ec.user.userId
if (!userId) userId = currentUserId
if (!userId) return
if (userId !== currentUserId && !ec.artifactExecution.authzDisabled()) {
    ec.message.addError(`The chat rooms of user ${userId} are not yours to see`)
    return
}
const row = ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).one()
if (!row) return
const isDirect = row.roomTypeEnumId === 'CrtDirect'
const memberRow = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', userId).one()
isArchived = !!row.archivedDate
if (memberRow && (!memberRow.leftDate || isDirect)) {
    isMember = true
    level = isDirect ? 2 : (ROLE_LEVEL[memberRow.roleEnumId] || 2)
} else {
    const visibility = row.visibilityEnumId || DEFAULT_VISIBILITY[row.roomTypeEnumId] || 'CrvMembers'
    if (visibility === 'CrvUsers') {
        level = 1
    } else if (visibility === 'CrvRecord' && row.recordEntityName && row.recordId) {
        // the record's visibility is the app's: asked as the user, with the caller's authorization
        const out = ec.service.sync().name('org.moqui.impl.ChatServices.check#RecordVisible')
                .parameters({recordEntityName: row.recordEntityName, recordId: row.recordId}).call()
        if (out && out.recordVisible === true) level = 1
    }
    canJoin = level === 1 && !isArchived
}
if (level === 0) return
canRead = true
canPost = isMember && !isArchived
canModerate = level >= 3 && !isDirect
isOwner = level >= 4
room = {chatRoomId: row.chatRoomId, roomTypeEnumId: row.roomTypeEnumId ?? null, roomType: CODES[row.roomTypeEnumId] || null,
    roomName: row.roomName ?? null, topic: row.topic ?? null, avatarLocation: row.avatarLocation ?? null,
    visibilityEnumId: row.visibilityEnumId || DEFAULT_VISIBILITY[row.roomTypeEnumId] || 'CrvMembers',
    recordEntityName: row.recordEntityName ?? null, recordId: row.recordId ?? null, retentionDays: row.retentionDays ?? null,
    createdByUserId: row.createdByUserId ?? null, createdDate: toMillis(row.createdDate), archivedDate: toMillis(row.archivedDate),
    lastEventSeq: Number(row.lastEventSeq || 0), lastEventDate: toMillis(row.lastEventDate),
    lastMessageSeq: row.lastMessageSeq != null ? Number(row.lastMessageSeq) : null, lastMessageUserId: row.lastMessageUserId ?? null,
    lastMessageDate: toMillis(row.lastMessageDate), lastMessageSnippet: row.lastMessageSnippet ?? null}
if (memberRow) member = {chatRoomId: memberRow.chatRoomId, userId: memberRow.userId, roleEnumId: memberRow.roleEnumId ?? null,
    agentRef: memberRow.agentRef ?? null, joinedDate: toMillis(memberRow.joinedDate), leftDate: toMillis(memberRow.leftDate),
    lastReadEventSeq: Number(memberRow.lastReadEventSeq || 0), notificationLevelEnumId: memberRow.notificationLevelEnumId ?? null,
    isPinned: memberRow.isPinned === 'Y', isMuted: memberRow.isMuted === 'Y'}

const CODES = {CetMessage: 'message', CetEdit: 'edit', CetReaction: 'reaction', CetRedaction: 'redaction',
    CetMembership: 'membership', CetPin: 'pin', CetCall: 'call', CetPoll: 'poll', CetSystem: 'system'}
const snippetOf = (text, attachments) => {
    const shown = String(text || '').replace(/\s+/g, ' ').trim()
    if (shown) return shown.length > 140 ? shown.slice(0, 139) + '…' : shown
    const files = (attachments || []).map((file) => file.fileName).filter((name) => name)
    return files.length ? '📎 ' + files.join(', ') : ''
}
const room = ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).forUpdate(true).one()
if (!room) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const now = ec.user.nowTimestamp
eventSeq = Number(room.lastEventSeq || 0) + 1
const row = ec.entity.makeValue('moqui.chat.ChatEvent')
row.setFields({chatRoomId: chatRoomId, eventSeq: eventSeq, eventTypeEnumId: eventTypeEnumId, senderUserId: senderUserId || null,
    contentJson: content ? JSON.stringify(content) : null, bodyText: bodyText || null,
    replyToEventSeq: replyToEventSeq ?? null, threadRootEventSeq: threadRootEventSeq ?? null,
    editsEventSeq: editsEventSeq ?? null, relatesToEventSeq: relatesToEventSeq ?? null, sentDate: now}, true, null, null)
row.create()
room.set('lastEventSeq', eventSeq)
room.set('lastEventDate', now)
if (eventTypeEnumId === 'CetMessage' && threadRootEventSeq == null) {
    room.set('lastMessageSeq', eventSeq)
    room.set('lastMessageUserId', senderUserId || null)
    room.set('lastMessageDate', now)
    room.set('lastMessageSnippet', snippetOf(bodyText, content ? content.attachments : null) || null)
}
room.update()

let senderName = null
if (senderUserId) {
    const account = ec.entity.find('moqui.security.UserAccount').condition('userId', senderUserId)
            .selectField('userFullName').selectField('username').disableAuthz().one()
    if (account) senderName = account.userFullName || account.username || senderUserId
}
const body = content && content.body != null ? content.body : null
event = {chatRoomId: chatRoomId, eventSeq: eventSeq, eventTypeEnumId: eventTypeEnumId, type: CODES[eventTypeEnumId] || null,
    senderUserId: senderUserId || null, senderName: senderName, sentDate: Number(now), content: content || {},
    body: body, bodyText: bodyText || null, mentions: (content && content.mentions) || [],
    attachments: (content && content.attachments) || [], records: (content && content.records) || [],
    replyToEventSeq: replyToEventSeq ?? null, threadRootEventSeq: threadRootEventSeq ?? null,
    editsEventSeq: editsEventSeq ?? null, relatesToEventSeq: relatesToEventSeq ?? null}

const isDirect = room.roomTypeEnumId === 'CrtDirect'
memberUserIdList = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId)
        .selectField('userId').selectField('leftDate').list()).filter((member) => isDirect || !member.leftDate).map((member) => member.userId)
if (!noPush && memberUserIdList.length) {
    ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal').parameters({topic: 'chatRoom:' + chatRoomId,
        userIdList: memberUserIdList, message: {kind: 'event', chatRoomId: chatRoomId, eventSeq: eventSeq, event: event}}).call()
}

try {
    if (!ec.search.isAvailable()) return
    if (remove) ec.search.deleteDocument('MoquiChatEvent', `${chatRoomId}::${eventSeq}`)
    else ec.search.indexDocuments(ec.entity.getDataDocuments('MoquiChatEvent', {chatRoomId: chatRoomId, eventSeq: eventSeq}))
} catch (err) {
    ec.logger.error(`Could not ${remove ? 'remove' : 'index'} chat message ${chatRoomId}::${eventSeq} in the search index: ${err && err.message ? err.message : err}`)
}

const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const CODES = {CrtDirect: 'direct', CrtPrivate: 'private', CrtPublic: 'public', CrtRecord: 'record'}
const DEFAULT_VISIBILITY = {CrtDirect: 'CrvMembers', CrtPrivate: 'CrvMembers', CrtPublic: 'CrvUsers', CrtRecord: 'CrvRecord'}
roomList = []; unreadTotal = 0; mentionTotal = 0
const currentUserId = ec.user.userId
if (!userId) userId = currentUserId
if (!userId) return
if (userId !== currentUserId && !ec.artifactExecution.authzDisabled()) {
    ec.message.addError(`The chat rooms of user ${userId} are not yours to see`); return }
const memberRows = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('userId', userId).condition('leftDate', null).list())
const memberOf = {}
for (const row of memberRows) memberOf[row.chatRoomId] = row
const roomIds = Object.keys(memberOf)
let rooms = []
if (roomIds.length) {
    let find = ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', roomIds)
    if (!includeArchived) find = find.condition('archivedDate', null)
    if (recordEntityName) find = find.condition('recordEntityName', recordEntityName)
    if (recordId) find = find.condition('recordId', recordId)
    rooms = Array.from(find.list())
}
if (includeJoinable && filter !== 'direct') {
    let find = ec.entity.find('moqui.chat.ChatRoom').condition('visibilityEnumId', 'CrvUsers').condition('archivedDate', null)
    if (roomIds.length) find = find.condition('chatRoomId', 'not-in', roomIds)
    if (recordEntityName) find = find.condition('recordEntityName', recordEntityName)
    if (recordId) find = find.condition('recordId', recordId)
    for (const row of find.orderBy('-lastEventDate').limit(200).list()) rooms.push(row)
}
// the members of the direct rooms, for their names
const directIds = rooms.filter((row) => row.roomTypeEnumId === 'CrtDirect').map((row) => row.chatRoomId)
const directMembers = {}
if (directIds.length) {
    for (const row of ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', 'in', directIds).selectField('chatRoomId')
            .selectField('userId').orderBy('joinedDate').list()) (directMembers[row.chatRoomId] = directMembers[row.chatRoomId] || []).push(row.userId)
}
const userIds = new Set([userId])
for (const ids of Object.values(directMembers)) ids.forEach((id) => userIds.add(id))
rooms.forEach((row) => { if (row.lastMessageUserId) userIds.add(row.lastMessageUserId) })
const names = {}
for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', Array.from(userIds))
        .selectField('userId').selectField('userFullName').selectField('username').disableAuthz().list())
    names[account.userId] = account.userFullName || account.username || account.userId
const presenceUsers = new Set()
const text = searchText ? String(searchText).toLowerCase().trim() : ''
for (const row of rooms) {
    const member = memberOf[row.chatRoomId] || null
    const isDirect = row.roomTypeEnumId === 'CrtDirect'
    const lastRead = member ? Number(member.lastReadEventSeq || 0) : 0
    let unreadCount = 0, mentionCount = 0
    if (member && Number(row.lastEventSeq || 0) > lastRead) {
        unreadCount = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', row.chatRoomId)
                .condition('eventTypeEnumId', 'CetMessage').condition('eventSeq', 'greater', lastRead)
                .condition('redactedDate', null).condition('senderUserId', 'not-equals', userId).count()
        mentionCount = ec.entity.find('moqui.chat.ChatEventMention').condition('chatRoomId', row.chatRoomId)
                .condition('userId', userId).condition('eventSeq', 'greater', lastRead).count()
    }
    const others = isDirect ? (directMembers[row.chatRoomId] || []).filter((id) => id !== userId) : []
    const displayName = row.roomName || (isDirect ? (others.length ? others.map((id) => names[id] || id).join(', ') : names[userId] || userId) : row.chatRoomId)
    const item = {chatRoomId: row.chatRoomId, roomTypeEnumId: row.roomTypeEnumId ?? null, roomType: CODES[row.roomTypeEnumId] || null,
        roomName: row.roomName ?? null, displayName: displayName, topic: row.topic ?? null, avatarLocation: row.avatarLocation ?? null,
        visibilityEnumId: row.visibilityEnumId || DEFAULT_VISIBILITY[row.roomTypeEnumId] || 'CrvMembers',
        recordEntityName: row.recordEntityName ?? null, recordId: row.recordId ?? null, archivedDate: toMillis(row.archivedDate),
        lastEventSeq: Number(row.lastEventSeq || 0), lastEventDate: toMillis(row.lastEventDate) || toMillis(row.createdDate),
        isMember: !!member, roleEnumId: member ? member.roleEnumId ?? null : null,
        notificationLevelEnumId: member ? member.notificationLevelEnumId ?? null : null,
        isPinned: !!member && member.isPinned === 'Y', isMuted: !!member && member.isMuted === 'Y',
        lastReadEventSeq: lastRead, unreadCount: unreadCount, mentionCount: mentionCount,
        lastMessage: row.lastMessageSeq != null ? {eventSeq: Number(row.lastMessageSeq), senderUserId: row.lastMessageUserId ?? null,
            senderName: row.lastMessageUserId ? names[row.lastMessageUserId] || row.lastMessageUserId : null,
            sentDate: toMillis(row.lastMessageDate), snippet: row.lastMessageSnippet ?? null, redacted: row.lastMessageSnippet == null} : null,
        otherUserIdList: others, otherUserId: others.length === 1 ? others[0] : null, presence: null}
    if (text && !(`${displayName} ${row.topic || ''}`.toLowerCase().includes(text))) continue
    if (filter === 'unread' && !(unreadCount > 0 || mentionCount > 0)) continue
    if (filter === 'mentions' && !(mentionCount > 0)) continue
    if (filter === 'direct' && !isDirect) continue
    if (filter === 'rooms' && !(row.roomTypeEnumId === 'CrtPrivate' || row.roomTypeEnumId === 'CrtPublic')) continue
    if (filter === 'records' && row.roomTypeEnumId !== 'CrtRecord') continue
    if (item.otherUserId) presenceUsers.add(item.otherUserId)
    roomList.push(item)
}
roomList.sort((left, right) => {
    if (left.isMember !== right.isMember) return left.isMember ? -1 : 1
    if (left.isPinned !== right.isPinned) return left.isPinned ? -1 : 1
    const byDate = (right.lastEventDate || 0) - (left.lastEventDate || 0)
    return byDate !== 0 ? byDate : String(left.chatRoomId).localeCompare(String(right.chatRoomId))
})
if (limit != null && roomList.length > limit) roomList = roomList.slice(0, limit)
if (presenceUsers.size) {
    const statuses = ec.service.sync().name('org.moqui.impl.ChatServices.get#UserStatuses')
            .parameter('userIdList', Array.from(presenceUsers)).call()
    const statusMap = (statuses && statuses.statusMap) || {}
    for (const item of roomList) if (item.otherUserId && statusMap[item.otherUserId]) item.presence = statusMap[item.otherUserId].presence
}
for (const item of roomList) { unreadTotal += item.unreadCount; mentionTotal += item.mentionCount }

const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
room = null; member = null; access = null; memberList = []
const byRecord = !chatRoomId
if (!chatRoomId) {
    if (!recordEntityName || !recordId) { ec.message.addError('A chat room is named by chatRoomId, or by recordEntityName and recordId'); return }
    const bound = Array.from(ec.entity.find('moqui.chat.ChatRoom').condition('roomTypeEnumId', 'CrtRecord')
            .condition('recordEntityName', recordEntityName).condition('recordId', recordId).orderBy('createdDate').list())
    if (!bound.length) return
    chatRoomId = (bound.find((row) => !row.archivedDate) || bound[0]).chatRoomId
}
const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!out.canRead) { if (!byRecord) ec.message.addError(`Chat room ${chatRoomId} not found`); return }
room = out.room
member = out.member
access = {level: out.level, isMember: out.isMember, canRead: out.canRead, canJoin: out.canJoin, canPost: out.canPost,
    canModerate: out.canModerate, isOwner: out.isOwner, isArchived: out.isArchived}
const isDirect = room.roomTypeEnumId === 'CrtDirect'
const rows = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).orderBy('joinedDate').list())
        .filter((row) => isDirect || !row.leftDate)
const names = {}
if (rows.length) for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', rows.map((row) => row.userId))
        .selectField('userId').selectField('userFullName').selectField('username').disableAuthz().list())
    names[account.userId] = account.userFullName || account.username || account.userId
memberList = rows.map((row) => ({userId: row.userId, name: names[row.userId] || row.userId, roleEnumId: row.roleEnumId ?? null,
    joinedDate: toMillis(row.joinedDate), lastReadEventSeq: Number(row.lastReadEventSeq || 0), isAgent: row.roleEnumId === 'CmrAgent'}))

const TYPES = {direct: 'CrtDirect', private: 'CrtPrivate', public: 'CrtPublic', record: 'CrtRecord'}
const VISIBILITIES = {members: 'CrvMembers', users: 'CrvUsers', record: 'CrvRecord'}
const DEFAULT_VISIBILITY = {CrtDirect: 'CrvMembers', CrtPrivate: 'CrvMembers', CrtPublic: 'CrvUsers', CrtRecord: 'CrvRecord'}
chatRoomId = null; created = false
const userId = ec.user.userId
if (!userId) { ec.message.addError('No user to make a chat room for'); return }
const type = TYPES[roomTypeEnumId] || roomTypeEnumId
if (!Object.values(TYPES).includes(type)) { ec.message.addError(`Unknown chat room type ${roomTypeEnumId}`); return }
let visibility = VISIBILITIES[visibilityEnumId] || visibilityEnumId || DEFAULT_VISIBILITY[type]
if (type === 'CrtDirect' || type === 'CrtPrivate') visibility = 'CrvMembers'
else if (type === 'CrtPublic') visibility = 'CrvUsers'
else if (!['CrvMembers', 'CrvRecord'].includes(visibility)) visibility = 'CrvRecord'
const others = Array.from(new Set((memberUserIdList || []).map((id) => String(id || '').trim()).filter((id) => id && id !== userId)))
if (others.length) {
    const found = new Set(Array.from(ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', others)
            .condition(ec.entity.conditionFactory.makeCondition('disabled', 'not-equals', 'Y', true))
            .selectField('userId').disableAuthz().list()).map((row) => row.userId))
    const missing = others.filter((id) => !found.has(id))
    if (missing.length) { ec.message.addError(`User ${missing.join(', ')} not found`); return }
}
const now = ec.user.nowTimestamp
const levelFor = type === 'CrtPublic' ? 'CnlMentions' : 'CnlAll'
const pushRoom = (users, action) => users.forEach((user) => ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal')
        .parameters({topic: 'chatUser:' + user, userIdList: [user], message: {kind: 'room', action: action, chatRoomId: chatRoomId}}).call())
let directKey = null
if (type === 'CrtDirect') {
    directKey = [userId].concat(others).sort().join(',')
    const existing = ec.entity.find('moqui.chat.ChatRoom').condition('roomTypeEnumId', 'CrtDirect').condition('directKey', directKey)
            .orderBy('createdDate').limit(1).list()
    if (existing.length) {
        chatRoomId = existing[0].chatRoomId
        const mine = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', userId).one()
        if (mine && mine.leftDate) { mine.set('leftDate', null); mine.update(); pushRoom([userId], 'joined') }
        return
    }
} else if (type === 'CrtRecord') {
    if (!recordEntityName || !recordId) { ec.message.addError('A record room needs recordEntityName and recordId'); return }
    const internal = ec.artifactExecution.authzDisabled()
    if (!internal) {
        const check = ec.service.sync().name('org.moqui.impl.ChatServices.check#RecordVisible')
                .parameters({recordEntityName: recordEntityName, recordId: recordId}).call()
        if (!check || check.recordVisible !== true) { ec.message.addError(`Record ${recordEntityName} ${recordId} not found`); return }
    }
    const existing = Array.from(ec.entity.find('moqui.chat.ChatRoom').condition('roomTypeEnumId', 'CrtRecord')
            .condition('recordEntityName', recordEntityName).condition('recordId', recordId).orderBy('createdDate').list())
    const open = existing.find((row) => !row.archivedDate)
    if (open) {
        chatRoomId = open.chatRoomId
        const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
        if (ec.message.hasError()) return
        if (access.canJoin) ec.service.sync().name('org.moqui.impl.ChatServices.add#Member').parameter('chatRoomId', chatRoomId).call()
        else if (!access.canRead) { ec.message.addError('The room of this record is for its members'); chatRoomId = null }
        return
    }
} else if (!roomName || !String(roomName).trim()) {
    ec.message.addError('A room needs a name'); return
}
const room = ec.entity.makeValue('moqui.chat.ChatRoom')
room.setSequencedIdPrimary()
room.setFields({roomTypeEnumId: type, roomName: roomName ? String(roomName).trim() : (type === 'CrtRecord' ? recordId : null),
    topic: topic || null, avatarLocation: avatarLocation || null, visibilityEnumId: visibility,
    recordEntityName: type === 'CrtRecord' ? recordEntityName : null, recordId: type === 'CrtRecord' ? recordId : null,
    directKey: directKey, retentionDays: retentionDays ?? null, createdByUserId: userId, createdDate: now,
    lastEventSeq: 0, lastEventDate: now}, true, null, null)
room.create()
chatRoomId = room.chatRoomId
created = true
const members = [userId].concat(others)
for (const memberId of members) {
    const member = ec.entity.makeValue('moqui.chat.ChatRoomMember')
    member.setFields({chatRoomId: chatRoomId, userId: memberId,
        roleEnumId: type === 'CrtDirect' || memberId !== userId ? 'CmrMember' : 'CmrOwner', joinedDate: now, lastReadEventSeq: 0,
        notificationLevelEnumId: levelFor, isPinned: 'N', isMuted: 'N', addedByUserId: userId}, true, null, null)
    member.create()
}
if (type !== 'CrtDirect') {
    const appended = ec.service.sync().name('org.moqui.impl.ChatServices.append#Event').parameters({chatRoomId: chatRoomId,
        eventTypeEnumId: 'CetSystem', senderUserId: userId, content: {action: 'created', roomName: room.roomName ?? null,
        userIds: members}, noPush: true}).call()
    if (ec.message.hasError()) return
    ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).updateAll({lastReadEventSeq: appended.eventSeq})
}
pushRoom(members, 'joined')

const VISIBILITIES = {members: 'CrvMembers', users: 'CrvUsers', record: 'CrvRecord'}
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.isMember) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
if (access.room.roomTypeEnumId === 'CrtDirect') { ec.message.addError('A direct room has no settings'); return }
const room = ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', chatRoomId).forUpdate(true).one()
const changes = []
const given = (value) => value !== undefined && value !== null
if (given(roomName) || given(topic) || given(avatarLocation)) {
    if (!access.canModerate) { ec.message.addError('Only a moderator or owner may change the room'); return }
    if (given(roomName)) {
        const name = String(roomName).trim()
        if (!name) { ec.message.addError('A room needs a name'); return }
        if (name !== room.roomName) { room.set('roomName', name); changes.push({action: 'renamed', roomName: name}) }
    }
    if (given(topic) && (topic || null) !== (room.topic || null)) { room.set('topic', topic || null); changes.push({action: 'topic', topic: topic || null}) }
    if (given(avatarLocation)) room.set('avatarLocation', avatarLocation || null)
}
if (given(visibilityEnumId) || given(retentionDays) || given(archived)) {
    if (!access.isOwner) { ec.message.addError('Only an owner may change who may join, the retention or the archive'); return }
    if (given(visibilityEnumId)) {
        const visibility = VISIBILITIES[visibilityEnumId] || visibilityEnumId
        const allowed = room.roomTypeEnumId === 'CrtRecord' ? ['CrvMembers', 'CrvRecord'] : ['CrvMembers', 'CrvUsers']
        if (!allowed.includes(visibility)) { ec.message.addError(`A room of this type may not have visibility ${visibilityEnumId}`); return }
        room.set('visibilityEnumId', visibility)
    }
    if (given(retentionDays)) room.set('retentionDays', retentionDays > 0 ? retentionDays : null)
    if (given(archived) && archived !== !!room.archivedDate) {
        room.set('archivedDate', archived ? ec.user.nowTimestamp : null)
        changes.push({action: archived ? 'archived' : 'unarchived'})
    }
}
room.update()
for (const change of changes) {
    ec.service.sync().name('org.moqui.impl.ChatServices.append#Event').parameters({chatRoomId: chatRoomId,
        eventTypeEnumId: 'CetSystem', senderUserId: ec.user.userId, content: change}).call()
    if (ec.message.hasError()) return
}
for (const row of ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('leftDate', null).selectField('userId').list())
    ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal').parameters({topic: 'chatUser:' + row.userId,
        userIdList: [row.userId], message: {kind: 'room', action: 'changed', chatRoomId: chatRoomId}}).call()

const ROLES = {owner: 'CmrOwner', moderator: 'CmrModerator', member: 'CmrMember', agent: 'CmrAgent'}
addedUserIdList = []
const me = ec.user.userId
if (!me) { ec.message.addError('No user'); return }
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const room = access.room
if (access.isArchived) { ec.message.addError('The room is archived'); return }
let targets = Array.from(new Set((userIdList || []).concat(userId ? [userId] : []).map((id) => String(id || '').trim()).filter((id) => id)))
const joining = !targets.length || (targets.length === 1 && targets[0] === me && !access.isMember)
if (!targets.length) targets = [me]
let role = ROLES[roleEnumId] || roleEnumId || 'CmrMember'
if (joining) {
    if (access.isMember) return
    if (!access.canJoin) { ec.message.addError('You may not join this room'); return }
    role = 'CmrMember'
} else {
    if (!access.isMember) { ec.message.addError('Join the room before adding others'); return }
    if (room.roomTypeEnumId === 'CrtDirect') { ec.message.addError('A direct room has fixed members: start a new direct message'); return }
    if (!Object.values(ROLES).includes(role)) { ec.message.addError(`Unknown member role ${roleEnumId}`); return }
    if ((role !== 'CmrMember' || agentRef) && !access.canModerate) { ec.message.addError('Only a moderator or owner may give a role'); return }
    if (role === 'CmrOwner' && !access.isOwner) { ec.message.addError('Only an owner may add an owner'); return }
    const found = new Set(Array.from(ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', targets)
            .condition(ec.entity.conditionFactory.makeCondition('disabled', 'not-equals', 'Y', true))
            .selectField('userId').disableAuthz().list()).map((row) => row.userId))
    const missing = targets.filter((id) => !found.has(id))
    if (missing.length) { ec.message.addError(`User ${missing.join(', ')} not found`); return }
}
const now = ec.user.nowTimestamp
const lastSeq = Number(room.lastEventSeq || 0)
const level = room.roomTypeEnumId === 'CrtPublic' ? 'CnlMentions' : 'CnlAll'
for (const target of targets) {
    let row = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', target).one()
    if (row && !row.leftDate) continue
    if (row) {
        row.setFields({leftDate: null, joinedDate: now, roleEnumId: role, agentRef: agentRef || null,
            lastReadEventSeq: Math.max(Number(row.lastReadEventSeq || 0), lastSeq), addedByUserId: me}, true, null, null)
        row.update()
    } else {
        row = ec.entity.makeValue('moqui.chat.ChatRoomMember')
        row.setFields({chatRoomId: chatRoomId, userId: target, roleEnumId: role, agentRef: agentRef || null, joinedDate: now,
            lastReadEventSeq: lastSeq, notificationLevelEnumId: level, isPinned: 'N', isMuted: 'N', addedByUserId: me}, true, null, null)
        row.create()
    }
    addedUserIdList.push(target)
}
for (const target of addedUserIdList) {
    const appended = ec.service.sync().name('org.moqui.impl.ChatServices.append#Event').parameters({chatRoomId: chatRoomId,
        eventTypeEnumId: 'CetMembership', senderUserId: me, content: {action: joining ? 'join' : 'add', userId: target,
        roleEnumId: role, byUserId: me}}).call()
    if (ec.message.hasError()) return
    // the membership event itself is read for the new member
    ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', target)
            .updateAll({lastReadEventSeq: appended.eventSeq})
    ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal').parameters({topic: 'chatUser:' + target,
        userIdList: [target], message: {kind: 'room', action: 'joined', chatRoomId: chatRoomId}}).call()
}

const me = ec.user.userId
if (!userId) userId = me
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.isMember) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const room = access.room
const isDirect = room.roomTypeEnumId === 'CrtDirect'
const self = userId === me
const row = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', userId).one()
if (!row || row.leftDate) { if (!self) ec.message.addError(`User ${userId} is not in the room`); return }
if (!self) {
    if (isDirect) { ec.message.addError('A direct room has fixed members'); return }
    if (!access.canModerate) { ec.message.addError('Only a moderator or owner may take a member out'); return }
    if (row.roleEnumId === 'CmrOwner' && !access.isOwner) { ec.message.addError('Only an owner may take an owner out'); return }
}
const now = ec.user.nowTimestamp
row.set('leftDate', now)
row.update()
if (!isDirect) {
    ec.service.sync().name('org.moqui.impl.ChatServices.append#Event').parameters({chatRoomId: chatRoomId,
        eventTypeEnumId: 'CetMembership', senderUserId: me, content: {action: self ? 'leave' : 'remove', userId: userId, byUserId: me}}).call()
    if (ec.message.hasError()) return
    if (row.roleEnumId === 'CmrOwner') {
        const remaining = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('leftDate', null)
                .condition('roleEnumId', 'not-equals', 'CmrAgent').orderBy('joinedDate').list())
        if (remaining.length && !remaining.some((member) => member.roleEnumId === 'CmrOwner')) {
            const heir = remaining.find((member) => member.roleEnumId === 'CmrModerator') || remaining[0]
            heir.set('roleEnumId', 'CmrOwner')
            heir.update()
            ec.service.sync().name('org.moqui.impl.ChatServices.append#Event').parameters({chatRoomId: chatRoomId,
                eventTypeEnumId: 'CetMembership', senderUserId: me, content: {action: 'role', userId: heir.userId, roleEnumId: 'CmrOwner', byUserId: me}}).call()
        }
    }
}
ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal').parameters({topic: 'chatUser:' + userId,
    userIdList: [userId], message: {kind: 'room', action: 'left', chatRoomId: chatRoomId}}).call()
ec.service.sync().name('org.moqui.impl.ChatServices.publish#ChatCounts').parameter('userIdList', [userId]).call()

const ROLES = {owner: 'CmrOwner', moderator: 'CmrModerator', member: 'CmrMember', agent: 'CmrAgent'}
const role = ROLES[roleEnumId] || roleEnumId
if (!Object.values(ROLES).includes(role)) { ec.message.addError(`Unknown member role ${roleEnumId}`); return }
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.isMember) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
if (access.room.roomTypeEnumId === 'CrtDirect') { ec.message.addError('A direct room has no roles'); return }
if (!access.canModerate) { ec.message.addError('Only a moderator or owner may give a role'); return }
const row = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', userId).one()
if (!row || row.leftDate) { ec.message.addError(`User ${userId} is not in the room`); return }
if (!access.isOwner && (row.roleEnumId === 'CmrOwner' || role === 'CmrOwner' || role === 'CmrAgent')) {
    ec.message.addError('Only an owner may change an owner or make an owner or agent'); return }
if (row.roleEnumId === 'CmrOwner' && role !== 'CmrOwner') {
    const owners = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('leftDate', null)
            .condition('roleEnumId', 'CmrOwner').count()
    if (owners <= 1) { ec.message.addError('A room keeps at least one owner'); return }
}
if (row.roleEnumId === role && (agentRef == null || agentRef === row.agentRef)) return
row.set('roleEnumId', role)
if (agentRef != null) row.set('agentRef', agentRef || null)
row.update()
ec.service.sync().name('org.moqui.impl.ChatServices.append#Event').parameters({chatRoomId: chatRoomId,
    eventTypeEnumId: 'CetMembership', senderUserId: ec.user.userId, content: {action: 'role', userId: userId, roleEnumId: role,
    byUserId: ec.user.userId}}).call()
if (ec.message.hasError()) return
ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal').parameters({topic: 'chatUser:' + userId,
    userIdList: [userId], message: {kind: 'room', action: 'role', chatRoomId: chatRoomId}}).call()

const LEVELS = {all: 'CnlAll', mentions: 'CnlMentions', none: 'CnlNone'}
const me = ec.user.userId
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameter('chatRoomId', chatRoomId).call()
if (ec.message.hasError()) return
if (!access.isMember) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
const row = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', me).one()
if (notificationLevelEnumId) {
    const level = LEVELS[notificationLevelEnumId] || notificationLevelEnumId
    if (!Object.values(LEVELS).includes(level)) { ec.message.addError(`Unknown notification level ${notificationLevelEnumId}`); return }
    row.set('notificationLevelEnumId', level)
}
if (isMuted != null) row.set('isMuted', isMuted ? 'Y' : 'N')
if (isPinned != null) row.set('isPinned', isPinned ? 'Y' : 'N')
row.update()
ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal').parameters({topic: 'chatUser:' + me, userIdList: [me],
    message: {kind: 'room', action: 'settings', chatRoomId: chatRoomId, notificationLevelEnumId: row.notificationLevelEnumId ?? null,
    isMuted: row.isMuted === 'Y', isPinned: row.isPinned === 'Y'}}).call()
ec.service.sync().name('org.moqui.impl.ChatServices.publish#ChatCounts').parameter('userIdList', [me]).call()

const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const parse = (text) => { if (!text) return {}; try { const value = JSON.parse(text); return value && typeof value === 'object' ? value : {} } catch (err) { return {} } }
const CODES = {CetMessage: 'message', CetEdit: 'edit', CetReaction: 'reaction', CetRedaction: 'redaction',
    CetMembership: 'membership', CetPin: 'pin', CetCall: 'call', CetPoll: 'poll', CetSystem: 'system'}
const SHOWN = ['CetMessage', 'CetMembership', 'CetPin', 'CetCall', 'CetPoll', 'CetSystem']
room = null; access = null; eventList = []; hasMoreBefore = false; hasMoreAfter = false; lastReadEventSeq = null; memberList = []
const roomOut = ec.service.sync().name('org.moqui.impl.ChatServices.get#Room').parameters({chatRoomId: chatRoomId,
    recordEntityName: recordEntityName, recordId: recordId}).call()
if (ec.message.hasError() || !roomOut.room) return
room = roomOut.room; access = roomOut.access; memberList = roomOut.memberList
chatRoomId = room.chatRoomId
lastReadEventSeq = roomOut.member ? roomOut.member.lastReadEventSeq : null
const me = ec.user.userId
const size = Math.max(1, Math.min(200, Number(limit) || 50))
const cf = ec.entity.conditionFactory
const base = () => {
    let find = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId)
    if (pinnedOnly) return find.condition('eventTypeEnumId', 'CetMessage').condition('pinnedDate', 'not-equals', null).condition('redactedDate', null)
    if (threadRootEventSeq != null) return find.condition('eventTypeEnumId', 'CetMessage').condition(cf.makeCondition([
        cf.makeCondition('eventSeq', 'equals', threadRootEventSeq), cf.makeCondition('threadRootEventSeq', 'equals', threadRootEventSeq)], 'or'))
    return find.condition('eventTypeEnumId', 'in', SHOWN).condition('threadRootEventSeq', null)
}
let rows
if (pinnedOnly) {
    rows = Array.from(base().orderBy('-pinnedDate').limit(size + 1).list())
    hasMoreAfter = rows.length > size
    rows = rows.slice(0, size)
} else if (aroundSeq != null) {
    const half = Math.max(1, Math.floor(size / 2))
    const older = Array.from(base().condition('eventSeq', 'less', aroundSeq).orderBy('-eventSeq').limit(half + 1).list())
    const newer = Array.from(base().condition('eventSeq', 'greater-equals', aroundSeq).orderBy('eventSeq').limit(size - half + 1).list())
    hasMoreBefore = older.length > half
    hasMoreAfter = newer.length > size - half
    rows = older.slice(0, half).reverse().concat(newer.slice(0, size - half))
} else if (afterSeq != null) {
    rows = Array.from(base().condition('eventSeq', 'greater', afterSeq).orderBy('eventSeq').limit(size + 1).list())
    hasMoreAfter = rows.length > size
    rows = rows.slice(0, size)
    hasMoreBefore = base().condition('eventSeq', 'less-equals', afterSeq).count() > 0
} else {
    let find = base()
    if (beforeSeq != null) find = find.condition('eventSeq', 'less', beforeSeq)
    rows = Array.from(find.orderBy('-eventSeq').limit(size + 1).list())
    hasMoreBefore = rows.length > size
    rows = rows.slice(0, size).reverse()
    hasMoreAfter = beforeSeq != null && base().condition('eventSeq', 'greater-equals', beforeSeq).count() > 0
}
if (!rows.length) return
const seqs = rows.map((row) => Number(row.eventSeq))
// the latest edit of each edited message
const editSeqs = rows.filter((row) => row.lastEditEventSeq != null && !row.redactedDate).map((row) => Number(row.lastEditEventSeq))
const edits = {}
if (editSeqs.length) for (const edit of ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId)
        .condition('eventSeq', 'in', editSeqs).list()) edits[Number(edit.editsEventSeq)] = parse(edit.contentJson)
// the reactions that stand
const reactions = {}
for (const reaction of ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventTypeEnumId', 'CetReaction')
        .condition('relatesToEventSeq', 'in', seqs).condition('redactedDate', null).orderBy('eventSeq').list()) {
    const key = parse(reaction.contentJson).key
    if (!key) continue
    const target = Number(reaction.relatesToEventSeq)
    const byKey = reactions[target] = reactions[target] || {}
    const entry = byKey[key] = byKey[key] || {key: key, count: 0, userIds: [], mine: false}
    if (entry.userIds.includes(reaction.senderUserId)) continue
    entry.userIds.push(reaction.senderUserId)
    entry.count++
    if (reaction.senderUserId === me) entry.mine = true
}
// the messages replied to that are not on this page
const onPage = {}
rows.forEach((row) => { onPage[Number(row.eventSeq)] = row })
const replySeqs = Array.from(new Set(rows.filter((row) => row.replyToEventSeq != null).map((row) => Number(row.replyToEventSeq)).filter((seq) => !onPage[seq])))
const replied = Object.assign({}, onPage)
if (replySeqs.length) for (const row of ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId)
        .condition('eventSeq', 'in', replySeqs).list()) replied[Number(row.eventSeq)] = row
const userIds = new Set()
Object.values(replied).forEach((row) => { if (row.senderUserId) userIds.add(row.senderUserId) })
const names = {}
if (userIds.size) for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', Array.from(userIds))
        .selectField('userId').selectField('userFullName').selectField('username').disableAuthz().list())
    names[account.userId] = account.userFullName || account.username || account.userId
const removedLabel = ec.l10n.localize('Message removed')
const snippet = (row) => {
    if (!row || row.redactedDate) return null
    const text = String(row.bodyText || '').replace(/\s+/g, ' ').trim()
    return text.length > 100 ? text.slice(0, 99) + '…' : text
}
for (const row of rows) {
    const seq = Number(row.eventSeq)
    const content = parse(row.contentJson)
    const redacted = !!row.redactedDate
    const edit = edits[seq]
    const isMessage = row.eventTypeEnumId === 'CetMessage'
    const item = {chatRoomId: chatRoomId, eventSeq: seq, eventTypeEnumId: row.eventTypeEnumId, type: CODES[row.eventTypeEnumId] || null,
        senderUserId: row.senderUserId ?? null, senderName: row.senderUserId ? names[row.senderUserId] || row.senderUserId : null,
        sentDate: toMillis(row.sentDate), content: isMessage ? {} : content,
        body: redacted || !isMessage ? null : (edit && edit.body != null ? edit.body : content.body ?? null),
        bodyText: redacted ? null : row.bodyText ?? null,
        mentions: redacted ? [] : ((edit && edit.mentions) || content.mentions || []),
        attachments: redacted ? [] : (content.attachments || []), records: redacted ? [] : (content.records || []),
        replyToEventSeq: row.replyToEventSeq != null ? Number(row.replyToEventSeq) : null, replyTo: null,
        threadRootEventSeq: row.threadRootEventSeq != null ? Number(row.threadRootEventSeq) : null,
        threadReplyCount: Number(row.threadReplyCount || 0), threadLastDate: toMillis(row.threadLastDate),
        relatesToEventSeq: row.relatesToEventSeq != null ? Number(row.relatesToEventSeq) : null,
        edited: !!row.editedDate && !redacted, editedDate: redacted ? null : toMillis(row.editedDate),
        redacted: redacted, redactedDate: toMillis(row.redactedDate), removedLabel: redacted ? removedLabel : null,
        pinned: !!row.pinnedDate && !redacted, pinnedByUserId: row.pinnedDate ? row.pinnedByUserId ?? null : null,
        reactions: redacted ? [] : Object.values(reactions[seq] || {})}
    if (item.replyToEventSeq != null) {
        const target = replied[item.replyToEventSeq]
        item.replyTo = target ? {eventSeq: item.replyToEventSeq, senderUserId: target.senderUserId ?? null,
            senderName: target.senderUserId ? names[target.senderUserId] || target.senderUserId : null, snippet: snippet(target),
            redacted: !!target.redactedDate} : {eventSeq: item.replyToEventSeq, senderUserId: null, senderName: null, snippet: null, redacted: true}
    }
    eventList.push(item)
}

const decode = (text) => String(text || '').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'")
        .replace(/&#x([0-9a-f]+);/gi, (m, hex) => String.fromCodePoint(parseInt(hex, 16))).replace(/&#(\d+);/g, (m, dec) => String.fromCodePoint(Number(dec)))
        .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
const toText = (html) => decode(String(html || '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|li|h[1-6]|blockquote|pre|div)>/gi, '\n')
        .replace(/<[^>]*>/g, '')).replace(/[ \t ]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim()
const LEVEL_ALL = (row) => row.isMuted !== 'Y' && (row.notificationLevelEnumId || 'CnlAll') === 'CnlAll'
eventSeq = null; event = null
const me = ec.user.userId
let sender = me
if (senderUserId && senderUserId !== me) {
    if (!ec.artifactExecution.authzDisabled()) { ec.message.addError('A message is sent as yourself'); return }
    sender = senderUserId
}
if (!sender) { ec.message.addError('No user to send the message'); return }
const access = ec.service.sync().name('org.moqui.impl.ChatServices.get#RoomAccess').parameters({chatRoomId: chatRoomId, userId: sender}).call()
if (ec.message.hasError()) return
if (!access.canRead) { ec.message.addError(`Chat room ${chatRoomId} not found`); return }
if (!access.isMember) { ec.message.addError('Join the room to post in it'); return }
if (access.isArchived) { ec.message.addError('The room is archived'); return }
const room = access.room
const html = body ? String(body).trim() : ''
if (html.length > 65536) { ec.message.addError('The message is too long'); return }
const bodyText = toText(html)
const emptyBody = !bodyText && !/<img\b/i.test(html)
const attachmentIds = Array.from(new Set((chatAttachmentIdList || []).map((id) => String(id || '').trim()).filter((id) => id)))
if (emptyBody && !attachmentIds.length) { ec.message.addError('A message needs text or a file'); return }

let replyTo = null, threadRoot = null
if (replyToEventSeq != null) {
    const target = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', replyToEventSeq).one()
    if (!target || target.eventTypeEnumId !== 'CetMessage') { ec.message.addError(`Message ${replyToEventSeq} not found in the room`); return }
    replyTo = Number(target.eventSeq)
}
let rootRow = null
if (threadRootEventSeq != null) {
    rootRow = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId).condition('eventSeq', threadRootEventSeq).one()
    if (!rootRow || rootRow.eventTypeEnumId !== 'CetMessage') { ec.message.addError(`Message ${threadRootEventSeq} not found in the room`); return }
    if (rootRow.threadRootEventSeq != null) rootRow = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', chatRoomId)
            .condition('eventSeq', rootRow.threadRootEventSeq).one()
    threadRoot = Number(rootRow.eventSeq)
}
const attachmentRows = []
if (attachmentIds.length) {
    const rows = Array.from(ec.entity.find('moqui.chat.ChatAttachment').condition('chatAttachmentId', 'in', attachmentIds).list())
    for (const id of attachmentIds) {
        const row = rows.find((candidate) => candidate.chatAttachmentId === id)
        if (!row || row.chatRoomId !== chatRoomId || row.uploadedByUserId !== sender || row.eventSeq != null) {
            ec.message.addError(`Attachment ${id} not found`); return }
        attachmentRows.push(row)
    }
}
const records = (recordList || []).filter((record) => record && record.entity && record.id).slice(0, 20)
        .map((record) => ({entity: String(record.entity), id: String(record.id)}))

// the mentions: users, who may read the room
const mentioned = Array.from(new Set(Array.from(html.matchAll(/data-mention-id="([^"]*)"/g)).map((match) => decode(match[1]).trim())
        .filter((id) => id && id !== sender)))
const memberRows = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).list())
const memberOf = {}
memberRows.forEach((row) => { memberOf[row.userId] = row })
const isDirect = room.roomTypeEnumId === 'CrtDirect'
const current = (row) => row && (!row.leftDate || isDirect)
let mentionIds = []
if (mentioned.length) {
    const users = new Set(Array.from(ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', mentioned)
            .selectField('userId').disableAuthz().list()).map((row) => row.userId))
    mentionIds = mentioned.filter((id) => users.has(id) && (current(memberOf[id]) || room.visibilityEnumId === 'CrvUsers'))
}

const attachments = attachmentRows.map((row, index) => ({chatAttachmentId: row.chatAttachmentId, attachmentSeq: index + 1,
    fileName: row.fileName ?? null, contentType: row.contentType ?? null, fileSize: row.fileSize != null ? Number(row.fileSize) : null}))
const content = {body: html || null, mentions: mentionIds, attachments: attachments, records: records}
const appended = ec.service.sync().name('org.moqui.impl.ChatServices.append#Event').parameters({chatRoomId: chatRoomId,
    eventTypeEnumId: 'CetMessage', senderUserId: sender, content: content, bodyText: bodyText,
    replyToEventSeq: replyTo, threadRootEventSeq: threadRoot}).call()
if (ec.message.hasError()) return
eventSeq = appended.eventSeq
event = appended.event
const now = ec.user.nowTimestamp
attachmentRows.forEach((row, index) => { row.set('eventSeq', eventSeq); row.set('attachmentSeq', index + 1); row.update() })
if (rootRow) {
    rootRow.set('threadReplyCount', Number(rootRow.threadReplyCount || 0) + 1)
    rootRow.set('threadLastDate', now)
    rootRow.update()
}
// the sender has read it; in a direct room the members who left are back
const senderRow = memberOf[sender]
if (senderRow) { senderRow.set('lastReadEventSeq', eventSeq); senderRow.set('lastReadDate', now); senderRow.update() }
if (isDirect) for (const row of memberRows) {
    if (!row.leftDate) continue
    row.set('leftDate', null)
    row.update()
    ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal').parameters({topic: 'chatUser:' + row.userId,
        userIdList: [row.userId], message: {kind: 'room', action: 'joined', chatRoomId: chatRoomId}}).call()
}
// mentions: counted, and notified unless the member's level is none
if (mentionIds.length) {
    for (const id of mentionIds) {
        const mention = ec.entity.makeValue('moqui.chat.ChatEventMention')
        mention.setFields({chatRoomId: chatRoomId, eventSeq: eventSeq, userId: id}, true, null, null)
        mention.create()
    }
    const notify = mentionIds.filter((id) => !memberOf[id] || (memberOf[id].notificationLevelEnumId || 'CnlAll') !== 'CnlNone')
    if (notify.length) {
