for (const room of ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', rows.map((row) => row.chatRoomId))
        .condition('archivedDate', null).selectField('chatRoomId').selectField('lastEventSeq').list()) rooms[room.chatRoomId] = Number(room.lastEventSeq || 0)
for (const row of rows) {
    if (!(row.chatRoomId in rooms)) continue
    const lastRead = Number(row.lastReadEventSeq || 0)
    if (rooms[row.chatRoomId] <= lastRead) continue
    const roomUnread = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', row.chatRoomId)
            .condition('eventTypeEnumId', 'CetMessage').condition('eventSeq', 'greater', lastRead)
            .condition('redactedDate', null).condition('senderUserId', 'not-equals', userId).count()
    const roomMentions = ec.entity.find('moqui.chat.ChatEventMention').condition('chatRoomId', row.chatRoomId)
            .condition('userId', userId).condition('eventSeq', 'greater', lastRead).count()
    if (!roomUnread && !roomMentions) continue
    const level = row.notificationLevelEnumId || 'CnlAll'
    const effective = level === 'CnlNone' ? 'CnlNone' : (row.isMuted === 'Y' ? 'CnlMentions' : level)
    const counted = effective === 'CnlAll' ? roomUnread : (effective === 'CnlMentions' ? roomMentions : 0)
    roomCounts[row.chatRoomId] = {unread: roomUnread, mentions: roomMentions, counted: counted}
    if (effective === 'CnlAll') unread += roomUnread
    if (effective !== 'CnlNone') mentions += roomMentions
    total += counted
    if (counted > 0) unreadRoomCount++
}

