    const directOrCurrent = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('userId', me).selectField('chatRoomId')
            .selectField('leftDate').list())
    const ids = directOrCurrent.map((row) => row.chatRoomId)
    const directIds = new Set(ids.length ? Array.from(ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', ids)
            .condition('roomTypeEnumId', 'CrtDirect').selectField('chatRoomId').list()).map((row) => row.chatRoomId) : [])
    myRooms = directOrCurrent.filter((row) => !row.leftDate || directIds.has(row.chatRoomId)).map((row) => row.chatRoomId)
}
const names = {}
const roomNames = {}
const finish = () => {
    const userIds = Array.from(new Set(eventList.map((item) => item.senderUserId).filter((id) => id)))
    if (userIds.length) for (const account of ec.entity.find('moqui.security.UserAccount').condition('userId', 'in', userIds)
            .selectField('userId').selectField('userFullName').selectField('username').disableAuthz().list())
        names[account.userId] = account.userFullName || account.username || account.userId
    const roomIds = Array.from(new Set(eventList.map((item) => item.chatRoomId)))
    if (roomIds.length) for (const room of ec.entity.find('moqui.chat.ChatRoom').condition('chatRoomId', 'in', roomIds)
            .selectField('chatRoomId').selectField('roomName').list()) roomNames[room.chatRoomId] = room.roomName
    for (const item of eventList) {
        if (!item.senderName && item.senderUserId) item.senderName = names[item.senderUserId] || item.senderUserId
        if (!item.roomName) item.roomName = roomNames[item.chatRoomId] || null
    }
}
if (ec.search.isAvailable() && ec.search.indexExists({documentType: 'MoquiChatEvent'})) {
    const allowed = []
    if (myRooms.length) allowed.push({field: {name: 'chatRoomId', op: 'in', values: myRooms}})
    if (includePublic) allowed.push({field: {name: 'roomVisibilityEnumId', op: 'eq', value: 'CrvUsers'}})
    if (!allowed.length) return
    let result
    try {
        result = ec.search.search({documentType: 'MoquiChatEvent', query: {text: {terms: text, fields: 'all', match: 'prefix'}},
            filter: {bool: {any: allowed}}, offset: offset, limit: size, highlight: ['bodyText']})
    } catch (err) {
        ec.message.addMessage(`Invalid search: ${text} (${err && err.message ? err.message : err})`, 'danger')
        return
    }
    total = Number(result.total || 0)
    for (const hit of result.hits) {
        const body = hit.body || {}
        const highlights = hit.highlights && hit.highlights.bodyText
        const snippet = String(body.bodyText || '').replace(/\s+/g, ' ').trim()
        eventList.push({chatRoomId: body.chatRoomId, eventSeq: Number(body.eventSeq), roomName: body.roomName ?? null,
            senderUserId: body.senderUserId ?? null, senderName: body.senderName ?? null, sentDate: toMillis(body.sentDate),
            snippet: snippet.length > 160 ? snippet.slice(0, 159) + '…' : snippet,
            highlight: Array.isArray(highlights) ? highlights[0] : (highlights || null)})
    }
    finish()
    return
}
// without search: the text of the messages, in the rooms the user may read
let roomIds = myRooms.slice()
if (includePublic) for (const room of ec.entity.find('moqui.chat.ChatRoom').condition('visibilityEnumId', 'CrvUsers')
        .selectField('chatRoomId').list()) if (!roomIds.includes(room.chatRoomId)) roomIds.push(room.chatRoomId)
if (!roomIds.length) return
const words = text.split(/\s+/).filter((word) => word)
const find = () => {
    let found = ec.entity.find('moqui.chat.ChatEvent').condition('chatRoomId', 'in', roomIds).condition('eventTypeEnumId', 'CetMessage')
            .condition('redactedDate', null)
    for (const word of words) found = found.condition(cf.makeCondition('bodyText', 'like', `%${word}%`, false, true))
    return found
}
total = find().count()
for (const row of find().orderBy('-sentDate').offset(offset).limit(size).list()) {
    const snippet = String(row.bodyText || '').replace(/\s+/g, ' ').trim()
    eventList.push({chatRoomId: row.chatRoomId, eventSeq: Number(row.eventSeq), roomName: null, senderUserId: row.senderUserId ?? null,
        senderName: null, sentDate: toMillis(row.sentDate), snippet: snippet.length > 160 ? snippet.slice(0, 159) + '…' : snippet, highlight: null})
}
finish()

if (!agentRef) {
    const row = ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', chatRoomId).condition('userId', agentUserId).disableAuthz().one()
    agentRef = row ? row.agentRef : null
}
if (!agentRef) { ec.logger.info(`Chat agent ${agentUserId} of room ${chatRoomId} has no agentRef; no agent runs in the framework`); return }
ec.message.pushErrors()
try {
    ec.service.sync().name(agentRef).parameters({chatRoomId: chatRoomId, eventSeq: eventSeq, agentUserId: agentUserId,
        senderUserId: senderUserId, body: body, bodyText: bodyText, threadRootEventSeq: threadRootEventSeq}).call()
    if (ec.message.hasError()) ec.logger.error(`Chat agent service ${agentRef} failed for ${chatRoomId}::${eventSeq}: ${ec.message.errorsString}`)
} catch (err) {
    ec.logger.error(`Chat agent service ${agentRef} failed for ${chatRoomId}::${eventSeq}: ${err && err.message ? err.message : err}`)
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}

const toMillis = (value) => {
    if (value == null || value === '') return null
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const OFFLINE_AFTER = 3 * 60000
const CODES = {UpsOnline: 'online', UpsAway: 'away', UpsDnd: 'dnd', UpsInvisible: 'invisible'}
statusMap = {}; myStatus = null
const me = ec.user.userId
const ids = Array.from(new Set((userIdList || []).map((id) => String(id || '').trim()).filter((id) => id))).slice(0, 500)
if (!ids.length) return
const now = Number(ec.user.nowTimestamp)
const rows = {}
for (const row of ec.entity.find('moqui.security.UserStatus').condition('userId', 'in', ids).disableAuthz().list()) rows[row.userId] = row
const awayMinutes = {}
for (const pref of ec.entity.find('moqui.security.UserPreference').condition('userId', 'in', ids)
        .condition('preferenceKey', 'CHAT_AUTO_AWAY_MINUTES').disableAuthz().list()) {
    const minutes = Number(pref.preferenceValue)
    if (minutes > 0) awayMinutes[pref.userId] = minutes
}
for (const id of ids) {
    const row = rows[id]
    const minutes = awayMinutes[id] || 10
    const expired = row && row.clearAtDate && toMillis(row.clearAtDate) <= now
    const chosen = row && !expired ? (row.statusEnumId || 'UpsOnline') : 'UpsOnline'
    const seen = row ? toMillis(row.lastSeenDate) : null
    const active = row ? toMillis(row.lastActiveDate) : null
    let presence
    if (!seen || now - seen > OFFLINE_AFTER || chosen === 'UpsInvisible') presence = 'offline'
    else if (chosen === 'UpsDnd') presence = 'dnd'
    else if (chosen === 'UpsAway') presence = 'away'
    else if (!active || now - active >= minutes * 60000) presence = 'away'
    else presence = 'online'
    const item = {userId: id, presence: presence, statusText: row && !expired ? row.statusText ?? null : null,
        emoji: row && !expired ? row.emoji ?? null : null, clearAtDate: row && !expired ? toMillis(row.clearAtDate) : null,
        inCall: !!row && row.inCall === 'Y', lastActiveDate: active}
    statusMap[id] = item
    if (id === me) myStatus = Object.assign({}, item, {statusEnumId: chosen, status: CODES[chosen] || 'online', autoAwayMinutes: minutes,
        connected: !!seen && now - seen <= OFFLINE_AFTER})
}

published = false
const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#UserStatuses').parameter('userIdList', [userId]).call()
const item = out && out.statusMap ? out.statusMap[userId] : null
if (!item) return
const row = ec.entity.find('moqui.security.UserStatus').condition('userId', userId).disableAuthz().one()
if (!force && row && row.lastPresence === item.presence) return
if (row) { row.set('lastPresence', item.presence); row.update() }
const message = {userId: userId, presence: item.presence, statusText: item.statusText, emoji: item.emoji,
    clearAtDate: item.clearAtDate, inCall: item.inCall}
const roomIds = Array.from(ec.entity.find('moqui.chat.ChatRoomMember').condition('userId', userId).condition('leftDate', null)
        .selectField('chatRoomId').disableAuthz().list()).map((member) => member.chatRoomId)
const others = new Set()
if (roomIds.length) for (const member of ec.entity.find('moqui.chat.ChatRoomMember').condition('chatRoomId', 'in', roomIds)
        .condition('leftDate', null).selectField('userId').disableAuthz().list()) if (member.userId !== userId) others.add(member.userId)
const recipients = Array.from(others).slice(0, 2000)
if (recipients.length) ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal').parameters({topic: 'userStatus',
    userIdList: recipients, message: message}).call()
const CODES = {UpsOnline: 'online', UpsAway: 'away', UpsDnd: 'dnd', UpsInvisible: 'invisible'}
const expired = row && row.clearAtDate && Number(row.clearAtDate) <= Number(ec.user.nowTimestamp)
ec.service.sync().name('org.moqui.impl.ChatServices.push#Signal').parameters({topic: 'userStatus', userIdList: [userId],
    message: Object.assign({}, message, {self: true, status: row && !expired ? CODES[row.statusEnumId] || 'online' : 'online'})}).call()
published = true

const STATUSES = {online: 'UpsOnline', away: 'UpsAway', dnd: 'UpsDnd', invisible: 'UpsInvisible'}
myStatus = null
const me = ec.user.userId
if (!userId) userId = me
if (!userId) { ec.message.addError('No user to set the status of'); return }
if (userId !== me && !ec.artifactExecution.authzDisabled()) { ec.message.addError('You set only your own status'); return }
const chosen = statusEnumId || status
const statusId = chosen ? (STATUSES[chosen] || chosen) : null
if (statusId && !Object.values(STATUSES).includes(statusId)) { ec.message.addError(`Unknown status ${chosen}`); return }
const now = ec.user.nowTimestamp
let row = ec.entity.find('moqui.security.UserStatus').condition('userId', userId).forUpdate(true).one()
const created = !row
if (created) {
    row = ec.entity.makeValue('moqui.security.UserStatus')
    row.setFields({userId: userId, statusEnumId: 'UpsOnline'}, true, null, null)
}
if (statusId) row.set('statusEnumId', statusId)
if (clearStatus) {
    row.set('statusText', null); row.set('emoji', null); row.set('clearAtDate', null)
} else {
    if (statusText != null) {
        const text = String(statusText).trim()
        if (Array.from(text).length > 100) { ec.message.addError('A status is up to 100 characters'); return }
        row.set('statusText', text || null)
    }
    if (emoji != null) {
        const shown = String(emoji).trim()
        if (Array.from(shown).length > 16 || /[<>]/.test(shown)) { ec.message.addError('An emoji is a few characters'); return }
        row.set('emoji', shown || null)
    }
    if (clearAfterMinutes != null) row.set('clearAtDate', clearAfterMinutes > 0 ? String(Number(now) + clearAfterMinutes * 60000) : null)
    else if (clearAtDate != null) row.set('clearAtDate', clearAtDate)
}
row.set('statusSetDate', now)
if (userId === me) { row.set('lastSeenDate', now); row.set('lastActiveDate', now) }
if (created) row.create(); else row.update()
ec.service.sync().name('org.moqui.impl.ChatServices.publish#UserStatus').parameters({userId: userId, force: true}).call()
const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#UserStatuses').parameter('userIdList', [userId]).call()
myStatus = out.myStatus || (out.statusMap ? out.statusMap[userId] : null)

myStatus = null
const me = ec.user.userId
if (!me) return
const now = Number(ec.user.nowTimestamp)
let row = ec.entity.find('moqui.security.UserStatus').condition('userId', me).forUpdate(true).one()
const created = !row
if (created) {
    row = ec.entity.makeValue('moqui.security.UserStatus')
    row.setFields({userId: me, statusEnumId: 'UpsOnline'}, true, null, null)
}
row.set('lastSeenDate', String(now))
const before = row.lastActiveDate != null ? Number(row.lastActiveDate) : 0
let lastActive = null
if (idleSeconds != null) lastActive = now - Math.max(0, idleSeconds) * 1000
else if (active !== false) lastActive = now
if (lastActive != null && lastActive > before) row.set('lastActiveDate', String(lastActive))
if (created) row.create(); else row.update()
ec.service.sync().name('org.moqui.impl.ChatServices.publish#UserStatus').parameter('userId', me).call()
const out = ec.service.sync().name('org.moqui.impl.ChatServices.get#UserStatuses').parameter('userIdList', [me]).call()
myStatus = out.myStatus

clearedCount = 0; publishedCount = 0
const now = Number(ec.user.nowTimestamp)
const expired = Array.from(ec.entity.find('moqui.security.UserStatus').condition('clearAtDate', 'less-equals', String(now)).disableAuthz().list())
const users = new Set()
for (const row of expired) {
    try {
        row.setFields({statusText: null, emoji: null, clearAtDate: null, statusEnumId: 'UpsOnline'}, true, null, null)
        row.update()
        clearedCount++
        users.add(row.userId)
    } catch (err) {
        ec.logger.error(`Could not clear the status of user ${row.userId}: ${err && err.message ? err.message : err}`)
    }
}
for (const row of ec.entity.find('moqui.security.UserStatus').condition('lastPresence', 'in', ['online', 'away', 'dnd'])
        .selectField('userId').disableAuthz().list()) users.add(row.userId)
const forced = new Set(expired.map((row) => row.userId))
for (const userId of users) {
    ec.message.pushErrors()
    try {
        const out = ec.service.sync().name('org.moqui.impl.ChatServices.publish#UserStatus').disableAuthz()
                .parameters({userId: userId, force: forced.has(userId)}).call()
        if (ec.message.hasError()) ec.logger.error(`Could not publish the status of user ${userId}: ${ec.message.errorsString}`)
        else if (out && out.published) publishedCount++
    } catch (err) {
        ec.logger.error(`Could not publish the status of user ${userId}: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
